// GATEA-06: least privilege, asserted against the live catalog and by real
// attempts as each runtime principal. The human-readable matrix is
// docs/security/DB_PRIVILEGE_MATRIX.md (generated by
// docs/security/privilege_matrix.sql); this test keeps it true.

func catalogRows(t *testing.T, f *fixture, q string) []string {
	t.Helper()
	rows, err := f.admin.Query(f.ctx, q)
	if err != nil {
		t.Fatalf("catalog query: %v", err)
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var s string
		if err := rows.Scan(&s); err != nil {
			t.Fatal(err)
		}
		out = append(out, s)
	}
	return out
}

func TestPrivileges_CatalogInvariants(t *testing.T) {
	f := newFixture(t)
	for name, q := range map[string]string{
		"function executable by PUBLIC": `
			SELECT p.oid::regprocedure::text FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
			WHERE n.nspname = 'public'
			  AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = p.oid AND d.deptype = 'e')
			  AND EXISTS (SELECT 1 FROM aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) x
			              WHERE x.grantee = 0 AND x.privilege_type = 'EXECUTE')`,
		"SECURITY DEFINER without pinned search_path": `
			SELECT p.oid::regprocedure::text FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
			WHERE n.nspname = 'public' AND p.prosecdef
			  AND NOT COALESCE(array_to_string(p.proconfig, ',') LIKE 'search_path=pg_catalog, public%', false)`,
		"table writable by PUBLIC or deletable by an app role": `
			SELECT c.relname || ':' || r FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace,
			  unnest(ARRAY['serk_app','serk_publisher','serk_scheduler','serk_health','serk_monitor','serk_abuse']) r
			WHERE n.nspname = 'public' AND c.relkind = 'r'
			  AND (has_table_privilege(r, c.oid, 'DELETE') OR has_table_privilege(r, c.oid, 'TRUNCATE')
			       OR has_table_privilege(r, c.oid, 'TRIGGER') OR has_table_privilege(r, c.oid, 'REFERENCES'))`,
		"tenant-data table without forced RLS that serk_app can read": `
			SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
			WHERE n.nspname = 'public' AND c.relkind = 'r' AND NOT c.relforcerowsecurity
			  AND has_table_privilege('serk_app', c.oid, 'SELECT')
			  AND EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attname = 'tenant_id')`,
		"approval key material reachable by a runtime role": `
			SELECT r FROM unnest(ARRAY['serk_app','serk_publisher','serk_scheduler','serk_health']) r
			WHERE has_table_privilege(r, 'approval_keys', 'SELECT')
			   OR has_function_privilege(r, 'approval_key_install(uuid,text,bytea)', 'EXECUTE')
			   OR has_table_privilege(r, 'approval_attestations', 'INSERT')
			   OR has_table_privilege(r, 'approval_attestations', 'UPDATE')`,
		"abuse-limit role can read or write any table (it must use abuse_hit/abuse_blocked only)": `
			SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
			WHERE n.nspname = 'public' AND c.relkind = 'r'
			  AND (has_table_privilege('serk_abuse', c.oid, 'SELECT') OR has_table_privilege('serk_abuse', c.oid, 'INSERT')
			       OR has_table_privilege('serk_abuse', c.oid, 'UPDATE'))`,
		"monitoring role can read any table (it must see aggregates only)": `
			SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
			WHERE n.nspname = 'public' AND c.relkind = 'r' AND has_table_privilege('serk_monitor', c.oid, 'SELECT')`,
		"approval evidence writable or consumable by a runtime role": `
			SELECT r FROM unnest(ARRAY['serk_app','serk_publisher','serk_scheduler','serk_health','serk_monitor']) r
			WHERE has_table_privilege(r, 'approval_consumptions', 'INSERT') OR has_table_privilege(r, 'fiscal_period_closes', 'INSERT')`,
		"approval authority held by a non-tenant role": `
			SELECT r FROM unnest(ARRAY['serk_publisher','serk_scheduler','serk_health','serk_monitor']) r
			WHERE has_function_privilege(r, 'approval_authorize(jsonb)', 'EXECUTE')
			   OR has_function_privilege(r, 'workflow_decide_definition(uuid,text,text,text)', 'EXECUTE')
			   OR has_table_privilege(r, 'journals', 'UPDATE')
			   OR has_table_privilege(r, 'journals', 'INSERT')`,
		"runtime role with cluster-level power": `
			SELECT rolname FROM pg_roles
			WHERE (rolname IN ('serk_app','serk_publisher','serk_scheduler','serk_health','serk_relay','serk_monitor','serk_abuse') OR rolname LIKE 'serk\_t\_%')
			  AND (rolsuper OR rolcreaterole OR rolcreatedb OR rolbypassrls OR rolreplication)`,
	} {
		if bad := catalogRows(t, f, q); len(bad) > 0 {
			t.Errorf("%s: %s", name, strings.Join(bad, ", "))
		}
	}
}

// R-10: functions created by the migrator in the future must be closed by
// default (0008's per-schema form was a no-op; 0009 sets the global default).
func TestPrivileges_NewFunctionsAreClosedByDefault(t *testing.T) {
	f := newFixture(t)
	tx, err := f.admin.Begin(f.ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = tx.Rollback(f.ctx) }()
	if _, err := tx.Exec(f.ctx, `CREATE FUNCTION public.zz_default_acl_probe() RETURNS int LANGUAGE sql AS 'SELECT 1'`); err != nil {
		t.Fatal(err)
	}
	var open bool
	if err := tx.QueryRow(f.ctx, `SELECT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) x
		WHERE p.proname = 'zz_default_acl_probe' AND x.grantee = 0 AND x.privilege_type = 'EXECUTE')`).Scan(&open); err != nil {
		t.Fatal(err)
	}
	if open {
		t.Error("a newly created function is EXECUTE-able by PUBLIC: default privileges are not closed")
	}
}

// Real attempts, not just catalog reads: each non-tenant runtime principal is
// refused the helpers and the approval boundary.
func TestPrivileges_NonTenantRolesAreRefused(t *testing.T) {
	f := newFixture(t)
	for _, group := range []string{"serk_health", "serk_publisher", "serk_scheduler", "serk_monitor"} {
		dsn := f.db.LoginRole(t, group)
		conn, err := pgx.Connect(f.ctx, dsn)
		if err != nil {
			t.Fatalf("%s: connect: %v", group, err)
		}
		for name, stmt := range map[string]string{
			"run the ledger integrity scan": `SELECT count(*) FROM ledger_integrity_scan()`,
			"consult approval evidence":     `SELECT approval_require('journal.post','journal','x','x',ARRAY[]::text[],false)`,
			"submit an attestation":         `SELECT approval_authorize('{}'::jsonb)`,
			"compute a subject hash":        `SELECT approval_subject_hash('journal', gen_random_uuid()::text)`,
			"read journals":                 `SELECT count(*) FROM journals`,
			"take a workflow gate lock":     `SELECT workflow_gate_lock(gen_random_uuid(), 'x', true)`,
		} {
			_, err := conn.Exec(f.ctx, stmt)
			// Refused at the function boundary itself, not later by a table
			// grant inside the function body.
			want := "permission denied for function"
			if strings.Contains(stmt, "FROM journals") {
				want = "permission denied" // RLS policy (current_tenant) or table grant
			}
			if err == nil || !strings.Contains(err.Error(), want) {
				t.Errorf("%s could %s (err=%v)", group, name, err)
			}
		}
		_ = conn.Close(context.Background())
	}
}

// The tenant runtime keeps exactly what its own flow needs and nothing that
// would let it rewrite history.
func TestPrivileges_TenantLoginCannotRewriteHistory(t *testing.T) {
	f := newFixture(t)
	for name, stmt := range map[string]string{
		"delete a journal":                 `DELETE FROM journals`,
		"truncate journal lines":           `TRUNCATE journal_lines`,
		"disable the attestation guard":    `ALTER TABLE journals DISABLE TRIGGER USER`,
		"delete approval evidence":         `DELETE FROM approval_attestations`,
		"rewrite approval evidence":        `UPDATE approval_attestations SET actor = 'someone'`,
		"edit a journal line amount":       `UPDATE journal_lines SET amount = amount + 1`,
		"rewrite the audit log":            `UPDATE audit_log SET actor_id = actor_id`,
		"drop the audit chain":             `DELETE FROM audit_log`,
		"change a journal's business date": `UPDATE journals SET business_event_at = business_event_at + interval '1 day'`,
	} {
		err := f.rawExec(stmt)
		denied(t, name, err)
		// Refused by privilege, not by a typo in the attack statement.
		if err != nil && !strings.Contains(err.Error(), "permission denied") && !strings.Contains(err.Error(), "must be owner") {
			t.Errorf("%s: refused for the wrong reason: %v", name, err)
		}
	}
}

// The monitoring login sees health aggregates and nothing else.
func TestPrivileges_MonitorSeesAggregatesOnly(t *testing.T) {
	f := newFixture(t)
	conn, err := pgx.Connect(f.ctx, f.db.LoginRole(t, "serk_monitor"))
	if err != nil {
		t.Fatal(err)
	}
	defer conn.Close(context.Background())
	var n int
	if err := conn.QueryRow(f.ctx, `SELECT count(*) FROM ops_health_metrics()`).Scan(&n); err != nil || n < 10 {
		t.Fatalf("monitor cannot read health metrics: n=%d err=%v", n, err)
	}
	var tenants float64
	if err := conn.QueryRow(f.ctx, `SELECT value FROM ops_health_metrics() WHERE metric = 'tenants'`).Scan(&tenants); err != nil || tenants < 2 {
		t.Fatalf("aggregate tenants=%v err=%v", tenants, err)
	}
	for _, stmt := range []string{`SELECT count(*) FROM journals`, `SELECT count(*) FROM outbox`, `SELECT count(*) FROM tenants`,
		`SELECT * FROM ledger_integrity_scan()`, `SELECT audit_log_verify(gen_random_uuid())`} {
		if _, err := conn.Exec(f.ctx, stmt); err == nil || !strings.Contains(err.Error(), "permission denied") {
			t.Errorf("monitor could run %q (err=%v)", stmt, err)
		}
	}
}

// 0034: every RLS table carries the owner_maintenance policy (so a
// non-superuser schema owner can provision and monitor), and a tenant login
// calling an owner-rights function still sees only its own tenant.
func TestPrivileges_OwnerMaintenancePolicyEverywhere(t *testing.T) {
	f := newFixture(t)
	var missing string
	if err := f.admin.QueryRow(f.ctx, `SELECT COALESCE(string_agg(c.relname, ', ' ORDER BY c.relname), '')
		FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
		WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relrowsecurity
		  AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = c.oid AND p.polname = 'owner_maintenance')`).Scan(&missing); err != nil {
		t.Fatal(err)
	}
	if missing != "" {
		t.Errorf("RLS tables without owner_maintenance (a non-superuser owner cannot maintain them): %s", missing)
	}
	// From a tenant session the maintenance predicate is false, including
	// inside owner-rights (SECURITY DEFINER) functions.
	var inTenant bool
	if err := f.app.WithTenant(f.ctx, f.tenant, func(ctx context.Context, tx pgx.Tx) error {
		return tx.QueryRow(ctx, `SELECT serk_maintenance_session()`).Scan(&inTenant)
	}); err == nil && inTenant {
		t.Errorf("serk_maintenance_session() is true for a tenant login")
	}
	var leaked int
	if err := f.app.WithTenant(f.ctx, f.tenant, func(ctx context.Context, tx pgx.Tx) error {
		// current_tenant() and p2p_account_digest are owner-rights functions
		// a tenant may call; through them the tenant must not see others.
		return tx.QueryRow(ctx, `SELECT count(*) FROM tenants WHERE id <> current_tenant()`).Scan(&leaked)
	}); err != nil {
		t.Fatal(err)
	}
	if leaked != 0 {
		t.Errorf("a tenant login sees %d other tenants", leaked)
	}
}
